import { ColumnDef, Row } from '@tanstack/react-table';
import ViewIcon from '@/components/icons/ViewIcon';
import FileDownloadIcon from '@/components/icons/file/FileDownloadIcon';
import EditIcon from '@/components/icons/EditIcon';
import TrashIcon from '@/components/icons/TrashIcon';
import { LetterRequest } from '@/features/selfServices/types/letterRequest.types';
import { format } from 'date-fns';
import { cn } from '@/lib/utils';
import { endpoints } from '@/lib/axios/axios-global';
import DeletePopup from '@/components/Popups/DeletePopup';
import { useState } from 'react';
import { toast } from 'sonner';
import { resolvePublicStorageUrl } from '@/features/selfServices/utils/resolvePublicStorageUrl';

export type LetterRequestRow = LetterRequest & { refreshTable?: () => void };

type ColumnHandlers = {
    onView: (row: LetterRequest) => void;
    onEdit: (row: LetterRequest) => void;
};

const ActionsCell = ({ row, handlers }: { row: Row<LetterRequestRow>; handlers: ColumnHandlers }) => {
    const [showDeletePopup, setShowDeletePopup] = useState(false);
    const attachmentUrl = resolvePublicStorageUrl(row.original.attachment);

    const handleDownload = () => {
        if (!attachmentUrl) {
            toast.message('لا يوجد مرفق لهذا الطلب');
            return;
        }
        window.open(attachmentUrl, '_blank', 'noopener,noreferrer');
    };

    const handleSuccessDelete = () => {
        toast.success('تم حذف الطلب بنجاح');
        setShowDeletePopup(false);
        row.original.refreshTable?.();
    };

    return (
        <>
            <div className="flex flex-row justify-center gap-4 flex-wrap">
                <button
                    type="button"
                    className="hover:bg-white-blue-300 rounded-full p-1"
                    title="عرض"
                    onClick={() => handlers.onView(row.original)}
                >
                    <ViewIcon className="cursor-pointer text-primery-blue-400 w-5 h-5" />
                </button>
                <button
                    type="button"
                    className="hover:bg-white-blue-300 rounded-full p-1 disabled:opacity-40"
                    title="تنزيل المرفق"
                    disabled={!attachmentUrl}
                    onClick={handleDownload}
                >
                    <FileDownloadIcon className="cursor-pointer text-primery-blue-400" />
                </button>
                <button
                    type="button"
                    className="hover:bg-white-blue-300 rounded-full p-1"
                    title="تعديل"
                    onClick={() => handlers.onEdit(row.original)}
                >
                    <EditIcon className="text-primery-blue-400 cursor-pointer" />
                </button>
                <button type="button" className="hover:bg-white-blue-300 rounded-full p-1" title="حذف" onClick={() => setShowDeletePopup(true)}>
                    <TrashIcon className="text-[#E81E1E] cursor-pointer" />
                </button>
            </div>
            {showDeletePopup && (
                <DeletePopup
                    open={showDeletePopup}
                    text="هل أنت متأكد أنك تريد حذف طلب الخطاب هذا؟"
                    endpoint={endpoints.letterRequests.delete + row.original.id}
                    handleCancel={() => setShowDeletePopup(false)}
                    handleSuccess={handleSuccessDelete}
                />
            )}
        </>
    );
};

export function createLetterColumns(handlers: ColumnHandlers): ColumnDef<LetterRequestRow>[] {
    return [
        {
            accessorKey: 'id',
            header: () => {
                return (
                    <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                        موجهه الى
                    </div>
                );
            },
            cell: ({ row }) => (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">{row.original.letter_for}</div>
            ),
        },
        {
            accessorKey: 'name',
            header: () => {
                return (
                    <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                        تاريخ الطلب
                    </div>
                );
            },
            cell: ({ row }) => (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {format(row.original.created_at, 'yyyy-MM-dd')}
                </div>
            ),
        },
        {
            accessorKey: 'name',
            header: () => {
                return (
                    <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                        تاريخ الخطاب
                    </div>
                );
            },
            cell: ({ row }) => (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {/* reserved if API adds letter_date */}
                </div>
            ),
        },
        {
            accessorKey: 'status',
            header: () => {
                return (
                    <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                        الحالة
                    </div>
                );
            },
            cell: ({ row }) => {
                return (
                    <div className="text-xs text-white-blue-50 font-medium tracking-normal leading-[115%]">
                        <p
                            className={cn('p-1 w-fit rounded-sm', {
                                'bg-[#DAF8E6] text-[#1A8245]': row.original.status === 'completed',
                                'bg-[#FFFBEB] text-[#D97706]': row.original.status === 'pending',
                                'bg-[#FEEBEB] text-[#E10E0E]': row.original.status === 'rejected',
                            })}
                        >
                            {row.original.status}
                        </p>
                    </div>
                );
            },
        },
        {
            id: 'actions',
            header: () => {
                return (
                    <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal"></div>
                );
            },
            cell: ({ row }) => <ActionsCell row={row} handlers={handlers} />,
        },
    ];
}
