import { cn } from '@/lib/utils';
import { useEffect, useState } from 'react';
import ServicesList from './servicesListTable/ServicesList';
import LettersList from './lettersListTable/LettersList';
import Reports from './reports/Reports';
import ComplaintsPage from './complaints/Complaints';

export default function SelectabelContent() {
    const [activeSection, setActiveSection] = useState(1);

    const searchParams = new URLSearchParams(window.location.search);
    const complaints = searchParams.get('complaints');

    const handleSelect = (value: number) => {
        setActiveSection(value);
    };
    
    useEffect(() => {
        if (complaints) {
            setActiveSection(2);
        }
    }, [complaints]);

    return (
        <div className="w-full mt-6">
            <div className="w-full overflow-x-auto rounded-lg [-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
                <div className="flex min-w-full flex-row items-stretch gap-[1px] sm:min-w-0">
                <button
                    onClick={() => handleSelect(1)}
                    className={cn(
                        'min-h-[48px] flex-1 whitespace-nowrap px-2 transition-colors text-xs sm:text-base py-3 text-white-blue-50 font-bold leading-[120%] tracking-normal rounded-s-lg sm:px-3',
                        {
                            'bg-primery-blue-700': activeSection === 1,
                            'bg-primery-blue-400': activeSection !== 1,
                        },
                    )}
                >
                    التقارير
                </button>
                <button
                    onClick={() => handleSelect(2)}
                    className={cn(
                        'min-h-[48px] flex-1 whitespace-nowrap px-2 transition-colors text-xs sm:text-base py-3 text-white-blue-50 font-bold leading-[120%] tracking-normal sm:px-3',
                        {
                            'bg-primery-blue-700': activeSection === 2,
                            'bg-primery-blue-400': activeSection !== 2,
                        },
                    )}
                >
                    الشكاوي
                </button>
                <button
                    onClick={() => handleSelect(3)}
                    className={cn(
                        'min-h-[48px] flex-1 whitespace-nowrap px-2 transition-colors text-xs sm:text-base py-3 text-white-blue-50 font-bold leading-[120%] tracking-normal sm:px-3',
                        {
                            'bg-primery-blue-700': activeSection === 3,
                            'bg-primery-blue-400': activeSection !== 3,
                        },
                    )}
                >
                    طلب خطاب
                </button>
                <button
                    onClick={() => handleSelect(4)}
                    className={cn(
                        'min-h-[48px] flex-1 whitespace-nowrap px-2 transition-colors text-xs sm:text-base py-3 text-white-blue-50 font-bold leading-[120%] tracking-normal rounded-e-lg sm:px-3',
                        {
                            'bg-primery-blue-700': activeSection === 4,
                            'bg-primery-blue-400': activeSection !== 4,
                        },
                    )}
                >
                    الخدمات الأضافية
                </button>
                </div>
            </div>
            {activeSection === 1 && <Reports />}
            {activeSection === 2 && <ComplaintsPage />}
            {activeSection === 3 && <LettersList />}
            {activeSection === 4 && <ServicesList />}
        </div>
    );
}
