import type { ReactNode } from 'react';
import { Dialog, DialogContent } from '@/components/ui/dialog';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { LetterRequest } from '@/features/selfServices/types/letterRequest.types';
import { resolvePublicStorageUrl } from '@/features/selfServices/utils/resolvePublicStorageUrl';
import { SelfServiceAttachmentPreview } from '@/features/selfServices/components/services/SelfServiceAttachmentPreview';
import { cn } from '@/lib/utils';

type Props = {
    open: boolean;
    onClose: () => void;
    record: LetterRequest | null;
};

function FieldRow({ label, children }: { label: string; children: ReactNode }) {
    return (
        <div className="rounded-xl border border-[#E8E7EA]/90 bg-white px-4 py-3 shadow-[0_1px_2px_rgba(12,12,13,0.04)]">
            <dt className="text-xs font-semibold uppercase tracking-wide text-[#90868C] mb-1">{label}</dt>
            <dd className="text-sm font-medium text-[#2D2D3A] leading-relaxed">{children}</dd>
        </div>
    );
}

function statusBadge(status: string) {
    const s = status?.toLowerCase();
    const map: Record<string, string> = {
        completed: 'bg-emerald-50 text-emerald-800 ring-emerald-600/15',
        pending: 'bg-amber-50 text-amber-800 ring-amber-600/15',
        rejected: 'bg-red-50 text-red-800 ring-red-600/15',
    };
    const cls = map[s] ?? 'bg-slate-50 text-slate-800 ring-slate-500/15';
    return (
        <span className={cn('inline-flex items-center rounded-md px-2.5 py-0.5 ring-1 ring-inset', cls)}>{status}</span>
    );
}

export function LetterRequestViewDialog({ open, onClose, record }: Props) {
    if (!record) return null;
    const attachmentUrl = resolvePublicStorageUrl(record.attachment);

    return (
        <Dialog open={open}>
            <div
                className={cn('fixed inset-0 bg-black/50 z-[999]', {
                    '!hidden': !open,
                })}
            />
            <DialogContent
                showCloseButton={false}
                className={cn(
                    'z-[1000] max-h-[90vh] max-w-2xl overflow-hidden flex flex-col p-0 gap-0',
                    'rounded-2xl border border-[#E8E7EA] bg-[#F4F6FA] font-cairo shadow-xl',
                    '[&_[aria-label=Close]]:opacity-0',
                )}
            >
                <div className="relative shrink-0 bg-gradient-to-l from-[#125592] to-[#145DA0] px-6 pt-6 pb-5 text-white">
                    <button
                        type="button"
                        onClick={onClose}
                        className="absolute top-4 end-4 flex h-9 w-9 items-center justify-center rounded-full bg-white/15 text-white hover:bg-white/25 transition-colors text-lg leading-none"
                        aria-label="إغلاق"
                    >
                        ×
                    </button>
                    <p className="text-xs font-medium text-white/80 mb-1">طلب خطاب</p>
                    <h3 className="text-xl font-bold tracking-tight">تفاصيل الطلب</h3>
                    <p className="text-sm text-white/85 mt-2 max-w-xl truncate" title={record.letter_for}>
                        موجّه إلى: <span className="font-semibold">{record.letter_for}</span>
                    </p>
                </div>

                <div className="flex-1 overflow-y-auto px-5 py-5 space-y-3">
                    <dl className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        <FieldRow label="موجّه إلى">{record.letter_for}</FieldRow>
                        <FieldRow label="الحالة">{statusBadge(record.status)}</FieldRow>
                        <FieldRow label="تاريخ الطلب">{new Date(record.created_at).toLocaleString()}</FieldRow>
                    </dl>

                    <FieldRow label="ملاحظات">
                        <span className="whitespace-pre-wrap font-normal">{record.note}</span>
                    </FieldRow>

                    {attachmentUrl ? (
                        <div className="space-y-2 pt-1">
                            <p className="text-xs font-semibold text-[#90868C] px-1">المرفق</p>
                            <SelfServiceAttachmentPreview rawPath={record.attachment} variant="hero" />
                        </div>
                    ) : (
                        <div className="rounded-xl border border-dashed border-[#D1D5DB] bg-white px-4 py-6 text-center text-sm text-[#90868C]">
                            لا يوجد ملف مرفق مع هذا الطلب
                        </div>
                    )}
                </div>

                <div className="shrink-0 flex gap-3 border-t border-[#E8E7EA] bg-white px-5 py-4">
                    <SecondaryButton type="button" className="flex-1 text-base py-2.5 font-medium" onClick={onClose}>
                        إغلاق
                    </SecondaryButton>
                    {attachmentUrl ? (
                        <PrimaryButton className="flex-1 text-base py-2.5 font-medium" asChild>
                            <a href={attachmentUrl} target="_blank" rel="noopener noreferrer">
                                فتح المرفق
                            </a>
                        </PrimaryButton>
                    ) : null}
                </div>
            </DialogContent>
        </Dialog>
    );
}
