import ReportSection from './ReportSection';
import OrdersList from './ordersTable/OrdersList';
import { Plane } from 'lucide-react';

export default function Requests({ employeeId }: { employeeId: number }) {
    return (
        <ReportSection
            icon={Plane}
            title="طلبات الإجازات"
            description="قائمة طلبات الإجازات المرتبطة بالموظف المحدد."
        >
            <div className="-mx-1 overflow-x-auto rounded-xl border border-slate-100 bg-slate-50/40 sm:mx-0">
                <OrdersList employeeId={employeeId} className="min-w-[min(100%,640px)] border-0 bg-transparent shadow-none" />
            </div>
        </ReportSection>
    );
}
