import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import NormalCard from '@/components/cards/NormalCard';
import ReportSection from './ReportSection';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { openPrintableReport } from '@/features/selfServices/utils/printReport';
import { resolvePublicStorageUrl } from '@/features/selfServices/utils/resolvePublicStorageUrl';
import { Download, FileText, Printer } from 'lucide-react';
import { useCallback, useEffect, useState } from 'react';

type ContractNested = {
    file?: string | null;
    position?: string | null;
    employee_number?: string | null;
};

type EmployeeShowPayload = {
    name?: string | null;
    email?: string | null;
    branch_name?: string | null;
    department?: string | null;
    position_name?: string | null;
    contract_start_date?: string | null;
    contract_end_date?: string | null;
    contract_sign_date?: string | null;
    contract_type?: string | null;
    main_salary?: number | string | null;
    contract?: ContractNested | null;
};

export default function ContractInfo({ employeeId }: { employeeId: number }) {
    const [data, setData] = useState<EmployeeShowPayload | null>(null);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.employee.show + employeeId });
                const payload = res.data?.data ?? res.data;
                if (!cancelled && payload && typeof payload === 'object') {
                    setData(payload as EmployeeShowPayload);
                }
            } catch {
                if (!cancelled) setData(null);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, [employeeId]);

    const contractFileUrl = resolvePublicStorageUrl(data?.contract?.file ?? null);

    const handlePrint = useCallback(() => {
        if (!data) return;
        const salary =
            data.main_salary != null && data.main_salary !== ''
                ? String(data.main_salary)
                : '—';
        openPrintableReport({
            title: `ملخص العقد — ${data.name ?? 'موظف'}`,
            subtitle: data.branch_name ? `الفرع: ${data.branch_name}` : undefined,
            rows: [
                { label: 'الاسم', value: data.name ?? '—' },
                { label: 'البريد', value: data.email ?? '—' },
                { label: 'الفرع', value: data.branch_name ?? '—' },
                { label: 'القسم', value: data.department ?? '—' },
                { label: 'المسمى الوظيفي', value: data.position_name ?? '—' },
                { label: 'نوع العقد', value: data.contract_type ?? '—' },
                { label: 'الراتب في العقد', value: salary },
                { label: 'تاريخ بداية العقد', value: data.contract_start_date ?? '—' },
                { label: 'تاريخ انتهاء العقد', value: data.contract_end_date ?? '—' },
                { label: 'تاريخ التوقيع', value: data.contract_sign_date ?? '—' },
                { label: 'رقم الموظف في العقد', value: data.contract?.employee_number ?? '—' },
            ],
        });
    }, [data]);

    return (
        <ReportSection
            accent
            icon={FileText}
            title="بيانات العقد"
            description="ملخص بيانات التعاقد والراتب والتواريخ. يمكن طباعة الملخص أو حفظه كـ PDF من نافذة الطباعة؛ وإن وُجد ملف عقد في السجل يُفتح في نافذة جديدة."
            actions={
                <>
                    <PrimaryButton type="button" onClick={handlePrint} disabled={!data} className="gap-2">
                        <Printer className="h-4 w-4 shrink-0" />
                        طباعة / PDF
                    </PrimaryButton>
                    {contractFileUrl ? (
                        <PrimaryButton
                            type="button"
                            className="gap-2 bg-emerald-700 hover:bg-emerald-800"
                            onClick={(e) => {
                                e.preventDefault();
                                e.stopPropagation();
                                window.open(contractFileUrl, '_blank', 'noopener,noreferrer');
                            }}
                        >
                            <Download className="h-4 w-4 shrink-0" />
                            تنزيل الملف
                        </PrimaryButton>
                    ) : (
                        <PrimaryButton type="button" disabled title="لا يوجد ملف عقد مرفوع في السجل">
                            <Download className="h-4 w-4 shrink-0 opacity-50" />
                            لا يوجد ملف
                        </PrimaryButton>
                    )}
                </>
            }
        >
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 sm:gap-4 xl:grid-cols-2">
                <NormalCard content={data?.name ?? '—'} title="اسم الموظف" />
                <NormalCard content={data?.branch_name ?? '—'} title="الفرع" />
                <NormalCard content={data?.department ?? '—'} title="القسم" />
                <NormalCard content={data?.position_name ?? '—'} title="المسمى الوظيفي" />
                <NormalCard content={data?.main_salary != null ? String(data.main_salary) : '—'} title="الراتب في العقد" />
                <NormalCard content={data?.contract_end_date ?? '—'} title="تاريخ انتهاء العقد" />
                <NormalCard content={data?.contract_start_date ?? '—'} title="تاريخ بداية العقد" />
                <NormalCard content={data?.contract_sign_date ?? '—'} title="تاريخ التوقيع" />
                <NormalCard content={data?.contract_type ?? '—'} title="نوع العقد" className="sm:col-span-2" />
            </div>
        </ReportSection>
    );
}
