import { useCallback, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { DataTableToolbar } from './data-table-toolbar';
import { columns, HolidayRequestRow } from './columns';
import { FetchDataOptions } from '@/types/table.types';
import { DataTable } from '@/components/tables/customTable/data-table';
import { cn } from '@/lib/utils';

interface Props {
    employeeId: number;
    className?: string;
}

export default function OrdersList({ employeeId, className }: Props) {
    const [data, setData] = useState<HolidayRequestRow[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);

    const fetchData = useCallback(
        async (options: FetchDataOptions) => {
            setIsLoading(true);
            try {
                const response = await apiGet({
                    endpoint: endpoints.holiday.list,
                    queryParams: {
                        page: options.pageIndex + 1,
                        employee_id: employeeId,
                        ...options.filters,
                        search: options.globalFilter,
                    },
                });
                setData(response.data.data.data);
                setPageCount(Math.ceil(response.data.data.pagination.total / 10));
                setTotalCount(response.data.data.pagination.total);
            } catch (error) {
                console.error('Error fetching data:', error);
            } finally {
                setIsLoading(false);
            }
        },
        [employeeId],
    );

    return (
        <div
            className={cn(
                'rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]',
                className,
            )}
        >
            <DataTable
                columns={columns}
                data={data}
                pageCount={pageCount}
                totalCount={totalCount}
                onFetchData={fetchData}
                DataTableToolbar={DataTableToolbar}
                isLoading={isLoading}
            />
        </div>
    );
}
