const esc = (s: string) =>
    s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

function schedulePrintAndMaybeClose(w: Window) {
    const cleanup = () => {
        try {
            w.close();
        } catch {
            /* ignore */
        }
    };

    const runPrint = () => {
        try {
            w.focus();
            w.print();
        } catch {
            cleanup();
            return;
        }
        // Closing immediately breaks print on some browsers; prefer afterprint when available
        const done = () => {
            w.removeEventListener('afterprint', done);
            cleanup();
        };
        w.addEventListener('afterprint', done);
        // Fallback if afterprint never fires (some browsers)
        window.setTimeout(() => {
            if (!w.closed) {
                cleanup();
            }
        }, 1200);
    };

    // Ensure document is loaded before print (avoids blank dialog / errors)
    if (w.document.readyState === 'complete') {
        window.setTimeout(runPrint, 0);
    } else {
        w.addEventListener('load', () => window.setTimeout(runPrint, 0), { once: true });
    }
}

/** Opens a print dialog; user can choose "Save as PDF" in the system print dialog. */
export function openPrintableReport(options: { title: string; subtitle?: string; rows: { label: string; value: string }[] }) {
    const w = window.open('', '_blank');
    if (!w) {
        return;
    }

    const rowsHtml = options.rows
        .map(
            (r) =>
                `<tr><td style="padding:10px;border:1px solid #ddd;font-weight:600;width:35%;">${esc(r.label)}</td><td style="padding:10px;border:1px solid #ddd;">${esc(r.value)}</td></tr>`,
        )
        .join('');

    const sub = options.subtitle ? `<p style="color:#555;margin:8px 0 16px;">${esc(options.subtitle)}</p>` : '';

    w.document.write(`<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8"/><title>${esc(options.title)}</title>
    <style>body{font-family:system-ui,Tahoma,sans-serif;padding:24px;color:#111;} table{border-collapse:collapse;width:100%;} h1{font-size:20px;margin:0 0 8px;}</style></head><body>
    <h1>${esc(options.title)}</h1>${sub}
    <table>${rowsHtml}</table>
    <p style="margin-top:24px;font-size:12px;color:#888;">تم الإنشاء من نظام الخدمات الذاتية</p>
    </body></html>`);
    w.document.close();
    schedulePrintAndMaybeClose(w);
}

/** Detailed month grid: status, check-in/out per day (browser print → Save as PDF). */
export function openPrintableAttendanceMonthly(options: {
    title: string;
    subtitle?: string;
    summaryRows: { label: string; value: string }[];
    dayRows: { date: string; status: string; checkIn: string; checkOut: string; notes: string }[];
}) {
    const w = window.open('', '_blank');
    if (!w) {
        return;
    }
    const sub = options.subtitle ? `<p style="color:#555;margin:8px 0 16px;">${esc(options.subtitle)}</p>` : '';
    const sumHtml = options.summaryRows
        .map(
            (r) =>
                `<tr><td style="padding:8px;border:1px solid #ddd;font-weight:600;">${esc(r.label)}</td><td style="padding:8px;border:1px solid #ddd;">${esc(r.value)}</td></tr>`,
        )
        .join('');
    const rowsHtml = options.dayRows
        .map(
            (r) =>
                `<tr><td style="padding:6px;border:1px solid #eee;">${esc(r.date)}</td><td style="padding:6px;border:1px solid #eee;">${esc(r.status)}</td><td style="padding:6px;border:1px solid #eee;">${esc(r.checkIn)}</td><td style="padding:6px;border:1px solid #eee;">${esc(r.checkOut)}</td><td style="padding:6px;border:1px solid #eee;">${esc(r.notes)}</td></tr>`,
        )
        .join('');

    w.document.write(`<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8"/><title>${esc(options.title)}</title>
    <style>body{font-family:system-ui,Tahoma,sans-serif;padding:20px;color:#111;} table{border-collapse:collapse;width:100%;font-size:13px;} h1{font-size:18px;margin:0 0 8px;} th,td{text-align:right;} th{background:#f0f4f8;}</style></head><body>
    <h1>${esc(options.title)}</h1>${sub}
    <h2 style="font-size:15px;margin:16px 0 8px;">ملخص</h2>
    <table style="margin-bottom:20px;"><tbody>${sumHtml}</tbody></table>
    <h2 style="font-size:15px;margin:16px 0 8px;">تفاصيل الأيام</h2>
    <table><thead><tr><th>التاريخ</th><th>الحالة</th><th>دخول</th><th>خروج</th><th>ملاحظات</th></tr></thead><tbody>${rowsHtml}</tbody></table>
    <p style="margin-top:20px;font-size:11px;color:#888;">تم الإنشاء من نظام الخدمات الذاتية — يمكن حفظ الصفحة كـ PDF من نافذة الطباعة</p>
    </body></html>`);
    w.document.close();
    schedulePrintAndMaybeClose(w);
}
