import Attendance from './Attendance';
import ContractInfo from './ContractInfo';
import Insurances from './Insurances';
import Loans from './Loans';
import Requests from './Requests';
import Salary from './Salary';
import { useSelfServiceEmployee } from '@/features/selfServices/context/SelfServiceEmployeeContext';
import { LayoutDashboard } from 'lucide-react';

export default function Reports() {
    const { effectiveEmployeeId, needsEmployeeSelection, ready, isPrivileged } = useSelfServiceEmployee();

    if (!ready) {
        return null;
    }

    if (needsEmployeeSelection || effectiveEmployeeId == null) {
        return (
            <div className="mx-auto mt-6 max-w-lg rounded-2xl border border-dashed border-slate-200 bg-slate-50/80 px-6 py-12 text-center shadow-sm">
                <LayoutDashboard className="mx-auto mb-4 h-12 w-12 text-slate-400" aria-hidden />
                <p className="font-cairo text-base leading-relaxed text-slate-700">
                    {isPrivileged
                        ? 'اختر موظفاً من القائمة أعلاه لعرض التقارير.'
                        : 'لا يوجد سجل موظف مرتبط بهذا الحساب.'}
                </p>
            </div>
        );
    }

    const id = effectiveEmployeeId;

    return (
        <div className="mx-auto w-full max-w-7xl px-3 pb-20 pt-1 sm:px-4 md:px-6">
            <div className="mb-6 rounded-2xl border border-primery-blue-100/90 bg-gradient-to-br from-primery-blue-50/90 via-white to-secondary-blue-50/50 px-4 py-5 shadow-sm sm:px-6 sm:py-6 md:mb-8">
                <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:gap-4">
                    <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-white shadow-sm ring-1 ring-primery-blue-100">
                        <LayoutDashboard className="h-6 w-6 text-primery-blue-600" aria-hidden />
                    </span>
                    <div className="min-w-0">
                        <h1 className="font-cairo text-xl font-bold tracking-tight text-primery-blue-950 sm:text-2xl">التقارير</h1>
                        <p className="mt-1 max-w-2xl text-sm leading-relaxed text-slate-600 sm:text-[15px]">
                            ملخص العقد، الحضور، الراتب، القروض، طلبات الإجازات، والتأمينات للموظف المحدد.
                        </p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 gap-4 md:gap-6 lg:grid-cols-2">
                <ContractInfo employeeId={id} />
                <Attendance employeeId={id} />
                <Loans employeeId={id} />
                <Salary employeeId={id} />
                <Insurances employeeId={id} />
                <div className="lg:col-span-2">
                    <Requests employeeId={id} />
                </div>
            </div>
        </div>
    );
}
