import { cn } from '@/lib/utils';

interface Props {
    title: string;
    subtitle?: string;
    content: string;
    className?: string;
}

export default function NormalCard({ content, subtitle, title, className }: Props) {
    return (
        <div
            className={cn(
                'rounded-2xl bg-secondary-blue-50 border-s-primery-blue-600 border-r-[3px] border-y-[0.5px] border-e-[0.5px] border-y-secondary-blue-200 border-e-secondary-blue-200 px-4 py-3 sm:px-6 sm:py-4 min-w-0',
                className,
            )}
        >
            <div className="flex flex-wrap items-baseline gap-x-2 gap-y-1">
                <p className="font-cairo font-semibold text-base leading-snug text-start text-[#333333] sm:text-[18px] md:text-[22px] md:leading-[150%]">
                    {title}
                </p>
                {subtitle && (
                    <p className="font-cairo text-xs font-medium leading-snug text-slate-600 sm:text-[14px]">{subtitle}</p>
                )}
            </div>
            <p className="mt-2 break-words font-cairo text-lg font-bold leading-snug text-start text-primery-blue-700 sm:text-xl md:text-[22px] md:leading-[150%]">
                {content}
            </p>
        </div>
    );
}
