import { useCallback, useMemo, useState, type ComponentProps } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { DataTableToolbar } from './data-table-toolbar';
import { createServiceColumns } from './columns';
import { FetchDataOptions } from '@/types/table.types';
import { DataTable } from '@/components/tables/customTable/data-table';
import { ExtraService } from '@/features/selfServices/types/extraServices.types';
import { useSelfServiceEmployee } from '@/features/selfServices/context/SelfServiceEmployeeContext';
import AskForService from '../popups/AskForService';
import { ServiceRequestViewDialog } from './ServiceRequestViewDialog';

export default function ServicesList() {
    const [data, setData] = useState<ExtraService[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const [tableKey, setTableKey] = useState(0);
    const [viewRecord, setViewRecord] = useState<ExtraService | null>(null);
    const [editRecord, setEditRecord] = useState<ExtraService | null>(null);
    const [askOpen, setAskOpen] = useState(false);
    const { effectiveEmployeeId, needsEmployeeSelection, ready } = useSelfServiceEmployee();

    const refreshList = useCallback(() => setTableKey((k) => k + 1), []);

    const fetchData = useCallback(
        async (options: FetchDataOptions) => {
            if (!ready || needsEmployeeSelection || effectiveEmployeeId == null) {
                setData([]);
                setPageCount(0);
                setTotalCount(0);
                setIsLoading(false);
                return;
            }
            setIsLoading(true);
            try {
                const response = await apiGet({
                    endpoint: endpoints.extraServices.list,
                    queryParams: {
                        page: options.pageIndex + 1,
                        employee_id: effectiveEmployeeId,
                        ...options.filters,
                        search: options.globalFilter,
                    },
                });
                setData(response.data.data.data);
                setPageCount(Math.ceil(response.data.data.pagination.total / 10));
                setTotalCount(response.data.data.pagination.total);
            } catch (error) {
                console.error('Error fetching data:', error);
            } finally {
                setIsLoading(false);
            }
        },
        [ready, needsEmployeeSelection, effectiveEmployeeId],
    );

    const columns = useMemo(
        () =>
            createServiceColumns({
                onView: (r) => setViewRecord(r),
                onEdit: (r) => {
                    setEditRecord(r);
                    setAskOpen(true);
                },
            }),
        [],
    );

    const Toolbar = useCallback((props: ComponentProps<typeof DataTableToolbar>) => {
        return (
            <DataTableToolbar
                {...props}
                onOpenNewService={() => {
                    setEditRecord(null);
                    setAskOpen(true);
                }}
            />
        );
    }, []);

    return (
        <div className="mt-6 mb-20 rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
            <DataTable
                key={tableKey}
                columns={columns}
                data={data}
                pageCount={pageCount}
                totalCount={totalCount}
                onFetchData={fetchData}
                DataTableToolbar={Toolbar}
                isLoading={isLoading}
            />
            <ServiceRequestViewDialog open={viewRecord != null} onClose={() => setViewRecord(null)} record={viewRecord} />
            <AskForService
                open={askOpen}
                setAskForService={(v) => {
                    setAskOpen(v);
                    if (!v) setEditRecord(null);
                }}
                handleRefreshTable={refreshList}
                editingRecord={editRecord}
            />
        </div>
    );
}
